// AWI: SEO TiTAN 7 DM - sekali jalan (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/titanfix', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$out = array();
			$aliasQ = 'Apakah BYD TiTAN 7 DM sama dengan BYD Ti7?';
			$aliasA = 'Ya. BYD TiTAN 7 DM adalah nama resmi di Indonesia untuk SUV yang sebelumnya dikenal sebagai BYD Ti7. Mobilnya sama: SUV plug-in hybrid 7 kursi dengan pilihan FWD DM-i dan AWD DM-p, dan bisa di-inden di BYD Haka Karebosi Makassar.';
			// Model page
			$c = $wpdb->get_var("SELECT post_content FROM {$wpdb->posts} WHERE ID=10706");
			$o = $c;
			$c = str_replace('<strong>BYD TiTAN 7 DM</strong> adalah SUV murni', '<strong>BYD TiTAN 7 DM</strong> (sebelumnya dikenal sebagai <strong>BYD Ti7</strong>) adalah SUV murni', $c);
			$c = str_replace('BYD Indonesia belum mengumumkan tanggal peluncuran resmi BYD TiTAN 7 DM. Pendaftaran inden bisa lewat dealer resmi, jadi daftar sekarang di BYD Haka Karebosi Makassar supaya dikabari pertama saat jadwal peluncuran dan unit tersedia.', 'Peluncuran BYD TiTAN 7 DM di BYD Haka Karebosi Makassar: 20 November 2026. Inden sudah dibuka, jadi daftar sekarang supaya dikabari pertama soal harga OTR Makassar dan jadwal unit tersedia.', $c);
			$h3 = '<h3 style="margin:16px 0 6px;">Kapan BYD TiTAN 7 DM meluncur di Indonesia?</h3>';
			if (strpos($c, $aliasQ) === false) $c = str_replace($h3, '<h3 style="margin:16px 0 6px;">' . $aliasQ . '</h3>' . "\n" . '<p style="margin:0 0 12px;line-height:1.6;">' . $aliasA . '</p>' . "\n" . $h3, $c);
			$c = str_replace('%20Ti7', '%20TiTAN%207%20DM', $c);
			$out['model'] = array('changed' => $c !== $o, 'alias' => substr_count($c, 'dikenal sebagai'), 'faqQ' => substr_count($c, $aliasQ), 'launch' => substr_count($c, '20 November 2026'), 'waTi7' => substr_count($c, '%20Ti7'));
			if ($c !== $o) { $wpdb->update($wpdb->posts, array('post_content' => $c), array('ID' => 10706)); clean_post_cache(10706); }
			// Article
			$c = $wpdb->get_var("SELECT post_content FROM {$wpdb->posts} WHERE ID=10818");
			$o = $c;
			$c = preg_replace('/(pilihan baru: (?:<strong>)?BYD TiTAN 7 DM(?:<\/strong>)?)(?! \(sebelumnya)/', '$1 (sebelumnya dikenal sebagai BYD Ti7)', $c, 1);
			$h3b = '<h3 style="font-size:19px;color:#111827;margin:20px 0 6px;">Berapa harga BYD TiTAN 7 DM di Makassar?</h3>';
			if (strpos($c, $aliasQ) === false) $c = str_replace($h3b, '<h3 style="font-size:19px;color:#111827;margin:20px 0 6px;">' . $aliasQ . '</h3><p style="margin:0 0 16px;">' . $aliasA . '</p>' . "\n" . $h3b, $c);
			$c = str_replace('%20Ti7', '%20TiTAN%207%20DM', $c);
			$out['article'] = array('changed' => $c !== $o, 'alias' => substr_count($c, 'dikenal sebagai'), 'faqQ' => substr_count($c, $aliasQ), 'waTi7' => substr_count($c, '%20Ti7'));
			if ($c !== $o) { $wpdb->update($wpdb->posts, array('post_content' => $c), array('ID' => 10818)); clean_post_cache(10818); }
			// Yoast
			$y = array(
				10706 => array('BYD TiTAN 7 DM (Ti7) Makassar: Harga, Spek & Inden', 'BYD TiTAN 7 DM (sebelumnya Ti7): SUV plug-in hybrid 7 kursi FWD & AWD, listrik hingga 155 km. Cek harga OTR Makassar & inden di dealer resmi BYD.', 'BYD TiTAN 7 DM'),
				10818 => array('BYD TiTAN 7 DM (Ti7) vs Fortuner & Pajero Sport | Makassar', 'BYD TiTAN 7 DM (Ti7) vs Fortuner & Pajero Sport: harian full listrik, AWD 0-100 km/jam 4,8 detik, garansi baterai 8 tahun. 7 keunggulan di Makassar.', 'BYD TiTAN 7 DM Makassar'),
			);
			foreach ($y as $id => $v) {
				update_post_meta($id, '_yoast_wpseo_title', $v[0]);
				update_post_meta($id, '_yoast_wpseo_metadesc', $v[1]);
				update_post_meta($id, '_yoast_wpseo_focuskw', $v[2]);
				update_post_meta($id, '_yoast_wpseo_opengraph-title', $v[0]);
				update_post_meta($id, '_yoast_wpseo_opengraph-description', $v[1]);
			}
			// WA prefill di snippet & halaman lain
			$t = $wpdb->prefix . 'snippets';
			$s = $wpdb->get_results("SELECT id, code FROM $t WHERE code LIKE '%\\%20Ti7%'");
			foreach ($s as $r) { $wpdb->update($t, array('code' => str_replace('%20Ti7', '%20TiTAN%207%20DM', $r->code)), array('id' => $r->id)); $out['snip'][] = $r->id; }
			$ps = $wpdb->get_col("SELECT ID FROM {$wpdb->posts} WHERE post_content LIKE '%\\%20Ti7%' AND post_type NOT IN ('revision') AND post_status='publish'");
			foreach ($ps as $pid) { $pc = get_post_field('post_content', $pid); $wpdb->update($wpdb->posts, array('post_content' => str_replace('%20Ti7', '%20TiTAN%207%20DM', $pc)), array('ID' => $pid)); clean_post_cache($pid); $out['otherposts'][] = $pid; }
			$bs = chr(92);
			if (function_exists('Code_Snippets' . $bs . 'clean_snippets_cache')) call_user_func('Code_Snippets' . $bs . 'clean_snippets_cache', $t);
			wp_cache_flush();
			return $out;
		},
	));
});

// AWI: FAQPage schema otomatis dari bagian FAQ (h3 + p) di halaman BYD TiTAN 7 DM & artikelnya. Dipasang Claude 19 Nov 2026.
add_action('wp_head', function () {
	if (!is_singular()) return;
	$id = get_queried_object_id();
	if (!in_array($id, array(10706, 10818), true)) return;
	$c = get_post_field('post_content', $id);
	$start = false;
	foreach (array('FAQ BYD TiTAN', 'Pertanyaan yang sering') as $k) { $start = stripos($c, $k); if ($start !== false) break; }
	if ($start === false) return;
	$sec = substr($c, $start);
	$end = stripos($sec, '<h2', 10);
	if ($end !== false) $sec = substr($sec, 0, $end);
	if (!preg_match_all('#<h3[^>]*>(.*?)</h3>\s*<p[^>]*>(.*?)</p>#s', $sec, $m, PREG_SET_ORDER)) return;
	$items = array();
	foreach ($m as $x) {
		$q = trim(html_entity_decode(wp_strip_all_tags($x[1]), ENT_QUOTES, 'UTF-8'));
		$a = trim(html_entity_decode(wp_strip_all_tags($x[2]), ENT_QUOTES, 'UTF-8'));
		if ($q && $a) $items[] = array('@type' => 'Question', 'name' => $q, 'acceptedAnswer' => array('@type' => 'Answer', 'text' => $a));
	}
	if (!$items) return;
	echo '<script type="application/ld+json">' . wp_json_encode(array('@context' => 'https://schema.org', '@type' => 'FAQPage', 'mainEntity' => $items), JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . '</script>' . "\n";
}, 30);
